<script setup>
import { onMounted, onUnmounted, reactive, ref } from 'vue'
import { api, errorMessage, localTime } from './api'
const clock = ref(new Date().toLocaleString()); let clockTimer
const state = ref(null), error = ref(''), busy = ref(false), accepted = ref(false)
const credentials = reactive({email:'',password:''}); let timer
async function refresh(){try{state.value=(await api.get('/local/status')).data}catch(err){error.value='Cannot reach the local agent. '+errorMessage(err)}}
async function login(){busy.value=true;error.value='';try{await api.post('/local/login',{...credentials,notice_accepted:accepted.value});credentials.password='';await refresh()}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
async function logout(){busy.value=true;try{await api.post('/local/logout');await refresh()}catch(err){error.value=errorMessage(err)}finally{busy.value=false}}
onMounted(async()=>{await refresh();timer=setInterval(refresh,3000);clockTimer=setInterval(()=>clock.value=new Date().toLocaleString(),1000)});onUnmounted(()=>{clearInterval(timer);clearInterval(clockTimer)})
</script>
<template><div class="agent-layout"><header><div class="brand dark"><span class="brand-symbol">a</span> activity<span class="brand-dot">.</span></div><span class="pill" :class="state?.tracking ? 'green' : 'neutral'">{{ state?.tracking ? '● Monitoring active' : 'Monitoring stopped' }}</span></header><main class="agent-main"><div v-if="!state" class="card">Connecting to the local agent…</div><template v-else><div class="eyebrow">EMPLOYEE DESKTOP AGENT</div><p class="mono" aria-label="Current local time">{{ clock }}</p><h1>{{ state.user ? 'Your device is connected' : 'Connect your workstation' }}</h1><p class="muted">{{ state.device_name }} · {{ state.server_url }}</p><div v-if="error" class="notice danger" role="alert">{{ error }}</div><section v-if="!state.user" class="card"><h2>Sign in to enroll this device</h2><form @submit.prevent="login"><label>Work email<input v-model.trim="credentials.email" type="email" autocomplete="username" required></label><label>Password<input v-model="credentials.password" type="password" autocomplete="current-password" required></label><div class="monitoring-notice"><strong>Monitoring notice</strong><p>{{ state.notice }}</p></div><label class="check-label"><input v-model="accepted" type="checkbox" required>I have read the monitoring notice. Monitoring starts after successful login.</label><button class="primary full" :disabled="busy || !accepted">{{ busy ? 'Signing in…' : 'Sign in & connect' }}</button></form></section><template v-else><section class="card"><div class="card-heading"><div><h2>{{ state.user.name }}</h2><small>{{ state.user.email }}</small></div><button @click="logout" :disabled="busy">Sign out</button></div><div class="monitoring-notice"><strong>{{ state.tracking ? 'Monitoring is active' : 'Monitoring is not active' }}</strong><p>{{ state.message }}</p><p>{{ state.notice }}</p></div><dl class="agent-details"><div><dt>Device identifier</dt><dd class="mono">{{ state.device_identifier }}</dd></div><div><dt>Screenshots</dt><dd>One random capture per {{ state.policy?.screenshot_interval_seconds }} seconds</dd></div><div><dt>Application sampling</dt><dd>Every {{ state.policy?.activity_interval_seconds }} seconds</dd></div><div><dt>Browser addresses</dt><dd>{{ state.policy?.browser_urls ? 'Enabled where supported' : 'Disabled' }}</dd></div></dl></section><div class="stats-grid agent-stats"><article class="stat"><span>Pending uploads</span><strong>{{ state.pending }}</strong><small>{{ state.queue_mb }} MB stored locally</small></article><article class="stat"><span>Last server contact</span><strong class="small-stat">{{ localTime(state.last_contact) }}</strong><small>Policy refreshes every 30 seconds</small></article></div><section class="card"><h2>Upload & capture status</h2><p v-if="state.failed_uploads" class="notice danger">{{ state.failed_uploads }} uploads need administrator inspection. Their files remain on this computer until retention expires.</p><p class="wrap">{{ state.upload_message }}</p><p class="wrap muted">{{ state.capture_message }}</p><p class="small muted">When offline, records queue on this computer within the configured storage limit. Monitoring settings and upload destinations are managed centrally.</p></section></template><p class="small muted">The agent runs in your signed-in Windows session. Closing this browser tab does not close the agent. The tray icon and console show its status.</p></template></main></div></template>
